using System;
using Betta.Attributes;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided facade piece, passed between components as a single "Panel" wire.</summary>
    [GrasshopperOpaque]
    public class Panel
    {
        public Panel() : this(new Point3d[4], 0) { }

        public Panel(Point3d[] corners, int index)
        {
            Corners = corners;
            Index = index;
        }

        public Point3d[] Corners { get; }
        public int Index { get; }

        public Curve Outline
        {
            get
            {
                var c = Corners;
                return new Polyline(new[] { c[0], c[1], c[2], c[3], c[0] }).ToNurbsCurve();
            }
        }

        public double Area => 0.5 * (Vector3d.CrossProduct(Corners[2] - Corners[0], Corners[3] - Corners[1])).Length;

        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double Deviation
        {
            get
            {
                var plane = new Plane(Corners[0], Corners[1], Corners[2]);
                return plane.IsValid ? Math.Abs(plane.DistanceTo(Corners[3])) : 0.0;
            }
        }

        public Point3d Center => (Corners[0] + Corners[1] + Corners[2] + Corners[3]) / 4.0;

        /// <summary>Edge i runs from corner i to corner i + 1.</summary>
        public double Edge(int i) => Corners[i].DistanceTo(Corners[(i + 1) % 4]);

        public double Width => (Edge(0) + Edge(2)) / 2.0;
        public double Height => (Edge(1) + Edge(3)) / 2.0;

        public double[] Signature()
        {
            var edges = new[] { Edge(0), Edge(1), Edge(2), Edge(3) };
            var diagonals = new[] { Corners[0].DistanceTo(Corners[2]), Corners[1].DistanceTo(Corners[3]) };
            Array.Sort(edges);
            Array.Sort(diagonals);
            return new[] { edges[0], edges[1], edges[2], edges[3], diagonals[0], diagonals[1] };
        }
    }
}
