                for (int n = 0; n < parts.Count; n++)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    progress?.Report(100 * n / parts.Count);

                    var part = parts[n];
                    if (!Orientations(part).Any(o => FitsEmpty(o.w, o.h))) { unplaced++; continue; }

                    double pw = 0, ph = 0, px = 0, py = 0;
                    bool placed = false;

                    if (open)
                    {
                        foreach (var o in Orientations(part))
                            if (x + o.w + spacing <= sheetWidth && o.h <= shelfH)
                            { pw = o.w; ph = o.h; px = x; py = shelfY; placed = true; break; }
                        if (!placed)
                        {
                            double newY = shelfY + shelfH + spacing;
                            foreach (var o in Orientations(part))
                                if (spacing + o.w + spacing <= sheetWidth && newY + o.h + spacing <= sheetHeight)
                                { pw = o.w; ph = o.h; px = spacing; py = newY; shelfY = newY; shelfH = o.h; placed = true; break; }
                        }
                    }
                    if (!placed)
                    {
                        sheet++;
                        foreach (var o in Orientations(part))
                            if (FitsEmpty(o.w, o.h))
                            { pw = o.w; ph = o.h; break; }
                        px = spacing; py = spacing; shelfY = spacing; shelfH = ph; open = true;
                    }

                    x = px + pw + spacing;
                    double ox = sheet * (sheetWidth + 100);
                    var rect = new Polyline(new[]
                    {
                        new Point3d(ox + px, py, 0), new Point3d(ox + px + pw, py, 0),
                        new Point3d(ox + px + pw, py + ph, 0), new Point3d(ox + px, py + ph, 0),
                        new Point3d(ox + px, py, 0),
                    });
                    outlines.Add(rect.ToNurbsCurve());
                    sheets.Add(sheet);
                    placedArea += pw * ph;
                }
                progress?.Report(100);

                if (unplaced > 0)
                    report.Warning($"{unplaced} panels fit on no sheet.");

                int sheetCount = sheet + 1;
                double utilization = sheetCount == 0 ? 0 : placedArea / (sheetCount * sheetWidth * sheetHeight);
                return (outlines, sheets, sheetCount, utilization);
            }, cancellationToken);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Path is empty.");

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("Index,Width,Height,Area,Deviation\n");
            foreach (var p in panels)
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.Width.ToString("R", inv)).Append(',')
                  .Append(p.Height.ToString("R", inv)).Append(',')
                  .Append(p.Area.ToString("R", inv)).Append(',')
                  .Append(p.Deviation.ToString("R", inv)).Append('\n');

            var csv = sb.ToString();
            if (!write) return (csv, false);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
